from datetime import datetime, timedelta

# Ensure access_token
access_token = None
try:
    access_token = resp.get('access_token')
except Exception as e:
    access_token = None

if not access_token:
    # login again
    venmo_password = None
    for item in apis.supervisor.show_account_passwords():
        if item['account_name']=='venmo':
            venmo_password = item['password']
            break
    creds_email = 'gra-martinez@gmail.com'
    access_token = apis.venmo.login(username=creds_email, password=venmo_password)['access_token']

print('token_prefix', access_token[:10])

# Time window: last 10 days including today
now = datetime.now()
start_dt = now - timedelta(days=9)
end_dt = now
print('now', now.isoformat())
print('start_dt', start_dt.isoformat())

# Fetch all received payment requests
page_index = 0
page_limit = 20
all_reqs = []
while True:
    page = apis.venmo.show_received_payment_requests(access_token=access_token, page_index=page_index, page_limit=page_limit)
    # page could be list or dict
    print('page_index', page_index, 'type', type(page))
    if isinstance(page, dict) and 'payment_requests' in page:
        items = page['payment_requests']
    elif isinstance(page, list):
        items = page
    else:
        # attempt to find first list-like value
        items = None
        if isinstance(page, dict):
            for v in page.values():
                if isinstance(v, list):
                    items = v
                    break
        if items is None:
            items = []
    print('items_count', len(items))
    if len(items)==0:
        break
    all_reqs.extend(items)
    page_index += 1
    if page_index>50:
        break

print('total_received_payment_requests_fetched', len(all_reqs))

# Inspect first record
if all_reqs:
    print('sample_record_keys', list(all_reqs[0].keys()))
    print('sample_created_at', all_reqs[0].get('created_at'))
    print('sample_amount', all_reqs[0].get('amount'))

# Parse and filter

def parse_iso(dt_str):
    if dt_str is None:
        return None
    s = str(dt_str)
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)

filtered = []
for r in all_reqs:
    c = parse_iso(r.get('created_at'))
    if c is None:
        continue
    if start_dt <= c <= end_dt:
        filtered.append(r)

print('filtered_count', len(filtered))

# Sum amounts
# Ensure numeric
amounts = []
for r in filtered:
    try:
        amounts.append(float(r.get('amount', 0.0)))
    except Exception:
        amounts.append(0.0)

total = sum(amounts)
print('total_amount', total)

# Print filtered records summary
for r in filtered[:10]:
